/* Lightweight Web Audio graph: voices → global colour/delay/space → limiter. */
(()=>{class StudioAudio{constructor(){this.ctx=null;this.voices=new Set();this.buffers=new WeakMap();this.offline=new WeakMap();this.fx={filter:0,echo:0,space:0,drive:0};this.ready=null;this.output=null}
async unlock(){if(!this.ctx){const C=globalThis.AudioContext||globalThis.webkitAudioContext;if(!C)throw Error('Audio indisponible dans ce navigateur.');const c=this.ctx=new C({latencyHint:'interactive'});this.input=c.createGain();this.hp=c.createBiquadFilter();this.hp.type='highpass';this.hp.frequency.value=20;this.lp=c.createBiquadFilter();this.lp.frequency.value=20000;this.drive=c.createWaveShaper();this.master=c.createGain();this.master.gain.value=.78;this.limiter=c.createDynamicsCompressor();this.limiter.threshold.value=-3;this.limiter.knee.value=4;this.limiter.ratio.value=12;this.limiter.attack.value=.003;this.limiter.release.value=.15;this.input.connect(this.hp).connect(this.lp).connect(this.drive).connect(this.master).connect(this.limiter).connect(c.destination);this.output=this.limiter;this.delay=c.createDelay(2);this.delay.delayTime.value=.27;this.feedback=c.createGain();this.feedback.gain.value=.3;this.delayWet=c.createGain();this.delayWet.gain.value=0;this.drive.connect(this.delay);this.delay.connect(this.feedback).connect(this.delay);this.delay.connect(this.delayWet).connect(this.master);this.verb=c.createConvolver();const impulse=c.createBuffer(2,c.sampleRate*1.8,c.sampleRate);let seed=1931;for(let ch=0;ch<2;ch++){const d=impulse.getChannelData(ch);for(let i=0;i<d.length;i++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;d[i]=(seed/2147483648-1)*Math.pow(1-i/d.length,2.5)}}this.verb.buffer=impulse;this.spaceWet=c.createGain();this.spaceWet.gain.value=0;this.drive.connect(this.verb).connect(this.spaceWet).connect(this.master);this.apply(this.fx)}if(this.ctx.state!=='running')await this.ctx.resume();return this.ctx}
getBuffer(p,c=this.ctx){let by=this.buffers.get(p.data);if(!by){by=new WeakMap();this.buffers.set(p.data,by)}let entry=by.get(c);if(!entry||entry.right!==p.right){const b=c.createBuffer(p.right?2:1,p.data.length,44100);b.copyToChannel(p.data,0);if(p.right)b.copyToChannel(p.right,1);entry={right:p.right,b};by.set(c,entry)}return entry.b}
play(p,index,{time=this.ctx.currentTime,token=null,pitch=0,velocity=1,duration=null,destination=this.input,context=this.ctx,force=false}={}){if(!p||p.data.length<2||p.muted&&!force)return null;const live=context===this.ctx;let collection=this.voices;if(!live){collection=this.offline.get(context);if(!collection){collection=new Set();this.offline.set(context,collection)}}{if(p.choke)for(const v of collection)if(v.choke===p.choke&&v.index!==index)this.release(v,time,false);if(live&&p.mode==='loop'){const active=[...collection].filter(v=>v.index===index&&!v.stopped);if(active.length&&token!==null){for(const v of active)this.release(v,time,false);return null}}if(collection.size>=32)this.release(collection.values().next().value,time,false)}const b=this.getBuffer(p,context),src=context.createBufferSource(),g=context.createGain(),pan=context.createStereoPanner(),start=p.start*b.duration,len=(p.end-p.start)*b.duration;if(len<=0)return null;src.buffer=b;src.playbackRate.value=2**((p.pitch+pitch)/12);pan.pan.value=p.pan;const volume=p.volume*velocity,attack=Math.min(Math.max(.0001,p.attack/1000),len/src.playbackRate.value*.3);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(volume,time+attack);src.connect(g).connect(pan).connect(destination);const v={src,g,pan,index,token,choke:p.choke,hold:p.mode==='hold',time,stopped:false,release:p.release/1000};src.loop=p.mode==='loop';src.loopStart=start;src.loopEnd=start+len;const end=p.mode==='loop'?null:time+len/src.playbackRate.value;if(end!==null){const fade=Math.min(.008,len/src.playbackRate.value/3);g.gain.setValueAtTime(volume,Math.max(time+attack,end-fade));g.gain.linearRampToValueAtTime(0,end);src.start(time,start,len)}else src.start(time,start);if(duration!==null){const off=time+duration;g.gain.cancelScheduledValues(off);g.gain.setValueAtTime(volume,off);g.gain.linearRampToValueAtTime(0,off+v.release);src.stop(off+v.release)}src.onended=()=>{src.disconnect();g.disconnect();pan.disconnect();collection.delete(v)};collection.add(v);return v}
release(v,time=this.ctx?.currentTime||0,soft=true){if(v.stopped)return;v.stopped=true;const t=Math.max(time,v.time),r=soft?Math.max(.005,v.release):.006;try{if(v.g.gain.cancelAndHoldAtTime)v.g.gain.cancelAndHoldAtTime(t);else{v.g.gain.cancelScheduledValues(t);v.g.gain.setValueAtTime(v.g.gain.value,t)}v.g.gain.linearRampToValueAtTime(0,t+r);v.src.stop(t+r)}catch{}}
off(token){for(const v of this.voices)if(v.token===token&&v.hold)this.release(v)}stop(index=null){for(const v of [...this.voices])if(index===null||v.index===index)this.release(v)}
apply(value){Object.assign(this.fx,value);if(!this.ctx)return;const c=this.ctx,t=c.currentTime,f=this.fx.filter;this.lp.frequency.setTargetAtTime(f<0?Math.max(180,20000*2**(f*7)):20000,t,.02);this.hp.frequency.setTargetAtTime(f>0?20*2**(f*9):20,t,.02);this.delayWet.gain.setTargetAtTime(this.fx.echo*.55,t,.02);this.spaceWet.gain.setTargetAtTime(this.fx.space*.7,t,.02);const amount=this.fx.drive;if(this.driveAmount!==amount){this.driveAmount=amount;if(amount===0)this.drive.curve=null;else{const curve=new Float32Array(2048),k=1+amount*14;for(let i=0;i<curve.length;i++)curve[i]=Math.tanh((i/(curve.length-1)*2-1)*k)/Math.tanh(k);this.drive.curve=curve}}}
}
globalThis.StudioAudio=StudioAudio})();
